export default async (ctx, client) => {
  const a = await client.agents.list({});
  const rows = (a?.agents ?? a?.data ?? a ?? []);
  return rows.map(x => ({
    id: x.id, name: x.name, model: x.model, models: x.models,
    installed_providers: x.installed_providers ?? x.installedProviders,
  }));
};

export default async (ctx, client) => {
  const out = {};
  for (const id of ['personal-agent', 'lobu-builder', 'personal-finance']) {
    const a = await client.agents.get({ agent_id: id });
    const x = a?.agent ?? a;
    out[id] = { model: x?.model, models: x?.models, providers: x?.installed_providers ?? x?.providers };
  }
  return out;
};

export default async (ctx, client) => {
  try {
    const r = await client.conversations.send({
      agent_id: 'personal-finance',
      thread: 'zz-glm-probe-0731',
      text: 'Reply with exactly: GLM OK',
      model: 'z-ai/glm-5.2',
      wait: true,
    });
    return { ok: true, reply: String(r?.text ?? r?.reply ?? JSON.stringify(r)).slice(0, 300) };
  } catch (e) {
    return { ok: false, error: String(e?.message ?? e).slice(0, 600) };
  }
};

export default async (ctx, client) => {
  const M = 'z-ai/glm-5.2';
  const plan = [
    { id: 71, model_config: { model: M }, execution_config: { model: M, permission_mode: 'dontAsk', timeout_seconds: 600 } },
    { id: 70, execution_config: { model: M, permission_mode: 'dontAsk', timeout_seconds: 900 } },
    { id: 5,  execution_config: { model: M, permission_mode: 'dontAsk', timeout_seconds: 600 } },
  ];
  const out = [];
  for (const p of plan) {
    const { id, ...patch } = p;
    try {
      await client.behaviors.update({ behavior_id: id, ...patch });
      out.push({ id, ok: true });
    } catch (e) { out.push({ id, ok: false, err: String(e?.message ?? e).slice(0, 300) }); }
  }
  return out;
};

