export default async (ctx, client) => {
  const out = {};
  try {
    const c = await client.conversations.list({ agent_id: 'personal-agent' });
    const rows = (c?.conversations ?? c?.data ?? c ?? []);
    out.recent = rows.slice(0, 10).map(x => ({ id: x.id, thread: x.thread ?? x.thread_key, updated: x.updated_at ?? x.last_message_at }));
