};

export default async (ctx, client) => {
  let found = null;
  for (let i = 0; i < 6; i++) {
    await ctx.sleep(28000);
    const r = await client.operations.listRuns({ behavior_ids: [71], limit: 3 });
    const rows = (r?.runs ?? r?.data ?? r ?? []);
    const sched = rows.find(x => x.id > 812011);
    if (sched && sched.status !== 'running' && sched.status !== 'pending') { found = sched; break; }
  }
  return {
    run: found ? { id: found.id, status: found.status, created: found.created_at,
                   secs: Math.round((new Date(found.completed_at) - new Date(found.created_at))/1000),
                   err: String(found.error_message ?? '').slice(0,200) } : 'no scheduled run yet',
  };
};

