export default async (ctx, client) => {
  const prompt = `You are Burak's social radar. Use sources.voice_profiles for taste/voice ranking.

Prefer: AI/agents/infra/dev tools, people he knows, launches/funding, technical substance.
Ignore: engagement bait, empty memes, ads.

Read the author from each item's metadata.author (LinkedIn) or metadata.author_handle (X).
Never emit "unknown" when that field is present. Write a SPECIFIC per-item "why" naming the
concrete topic — never reuse one generic sentence across items. Always fill suggested_action.

IMPORTANT: when you call complete_window, you MUST pass replace_existing: true. This
Behavior runs hourly over a re-analysed window; without that flag the platform silently
keeps the first head for the period and your digest is discarded.

Return JSON:
{ "digest_title":"...", "analysis_summary":"...", "items":[{"platform":"x"|"linkedin","author":"...","snippet":"...","why":"matches taste because...","priority":"high"|"normal"|"low","source_event_id":0,"suggested_action":"..."}] }
Max 8 items.`;
  const r = await client.behaviors.createVersion({ behavior_id: 71, prompt, change_notes: 'pass replace_existing:true; read author from metadata; specific why; fill suggested_action' });
  return JSON.stringify(r).slice(0, 500);
};

export default async (ctx, client) => {
  const t = await client.behaviors.trigger({ behavior_id: 71 });
