    await ctx.sleep(20000);
    const r = await client.operations.listRuns({ behavior_ids: [71], limit: 2 });
    const rows = (r?.runs ?? r?.data ?? r ?? []);
    const run = rows.find(x => x.id === runId);
    if (run && !['running','pending'].includes(run.status)) {
      return { runId, status: run.status, secs: Math.round((new Date(run.completed_at)-new Date(run.created_at))/1000), err: String(run.error_message ?? '').slice(0,300) };
    }
  }
  return { runId, timedout: true };
};

