export default async (ctx, client) => {
  const created = await client.classifiers.create({
    slug: "post-sentiment",
    name: "Post sentiment",
    description: "Sentiment of a social post or message.",
    attribute_key: "post_sentiment",
    min_similarity: 0.5,
    attribute_values: {
      positive: {
        description: "Enthusiastic, celebratory, praising, excited or grateful.",
        examples: ["this is amazing, so happy about it", "huge congrats, well deserved", "loving this, best thing all week"],
      },
      negative: {
        description: "Frustrated, critical, complaining, angry or disappointed.",
        examples: ["this is broken and infuriating", "worst experience, total waste of time", "really disappointed, they dropped the ball"],
      },
      neutral: {
        description: "Factual, informational or announcement with no emotional charge.",
        examples: ["the meeting is at 3pm on Tuesday", "version 2.1 is now available", "here is the link to the documentation"],
      },
    },
  });
  return created;
};

export default async (ctx, client) => {
  const listed = await client.classifiers.list({});
  const rows = (listed as any).data?.classifiers ?? listed;
  return (rows as any[]).map((c: any) => ({ id: c.classifier_id ?? c.id, slug: c.slug, behavior_id: c.behavior_id ?? c.watcher_id ?? null, status: c.status }));
};

export default async (ctx, client) => {
  const rows: any = await client.query(
    "SELECT id FROM events WHERE connector_key IN ('x','twitter.takeout') AND payload_text IS NOT NULL AND length(payload_text) BETWEEN 80 AND 400 ORDER BY id DESC LIMIT 500"
  );
  const list = Array.isArray(rows) ? rows : (rows?.rows ?? rows?.data ?? []);
  const ids = list.map((r: any) => Number(r.id));
  // 999999999 does not exist -> must come back as not_in_organization, not silence.
  const applied = await client.classifiers.apply({
    classifier_slug: "post-sentiment",
    content_ids: [...ids, 999999999],
  });
  return { requested_ids: ids.length + 1, applied };
};

