  const embed = async (t) => {
    const o = await extractor(t, { pooling: 'mean', normalize: true });
    return Array.from(o.data);
  };

  const labelVecs = {};
  for (const [k, v] of Object.entries(LABELS)) labelVecs[k] = await embed(prefixPassage + labelText(v));

