  const dist = { positive: 0, negative: 0, neutral: 0 };
  const sims = [];
  for (const ev of events) {
    const vec = await embed(prefixQuery + ev.text);
    let best = null, bestSim = -1;
    for (const [k, lv] of Object.entries(labelVecs)) {
