export default async (ctx, client) => {
  // Pick a few embedded events and re-apply the existing classifier.
  // upsert is DELETE+INSERT keyed on (event,classifier,source), so re-applying
  // already-labelled events is idempotent — this checks the engine still
  // produces templates now that the model-stamp guard is live.
  const rows = await client.query(`
    SELECT ec.event_id AS id
    FROM event_classifications ec
    WHERE ec.classifier_id = 201
    ORDER BY ec.event_id DESC
    LIMIT 5
  `);
  const ids = rows.map((r) => Number(r.id));
  const res = await client.classifiers.apply({
    classifier_slug: 'post-sentiment',
    content_ids: ids,
  });
  return { ids, apply: res };
};

