let dispatchedWindowStart: string | null = null;
let dispatchSource: string | null = null;
if (watcherRunId != null) {
  const runRows = await sql`
    SELECT (approved_input->>'version_id')::bigint AS version_id,
           approved_input->>'window_start'   AS window_start,
           approved_input->>'dispatch_source' AS dispatch_source
    FROM runs
    WHERE id = ${watcherRunId} AND watcher_id = ${watcherId}
    LIMIT 1
  `;
  if (runRows.length > 0) {
    if (snapshotVersionId == null && runRows[0].version_id != null) {
      snapshotVersionId = Number(runRows[0].version_id);
    }
    dispatchedWindowStart = (runRows[0].window_start as string | null) ?? null;
    dispatchSource = (runRows[0].dispatch_source as string | null) ?? null;
  }
