/**
 * A scheduled Behavior must complete the period it was dispatched for.
 *
 * `window_start` arrives inside a signed token, so an agent cannot forge one —
 * but it CAN steer which period gets minted, because `get_content` Behavior mode
 * honours `since`/`until` and mints the token for that range instead of the
 * dispatched window. Nothing downstream noticed: `findCanvasHead` matches the
 * token's period by exact equality, finds the previous root, supersedes it, and
 * the run reports success while the window never advances.
 *
 * Observed on prod, not hypothesised. Behavior 71 ("Social interest radar") ran
 * hourly for a full day dispatched `2026-07-30T23:59:59.999Z` while completing
 * `2026-07-30T00:00:00.000Z` — 13 scheduled runs, every one `completed`, the
 * digest correct but filed under the previous day forever. Across the six
 * Behaviors with scheduled completions the mismatch correlates perfectly with an
 * end-of-day window end (the `toEndOfDay` signature of the `since`/`until`
 * branch); the single Behavior whose periods match uses period-aligned ends on
 * all 22 of its windows.
 *
 * Fixing the window arithmetic alone (PR #2412) does NOT close this — that
 * corrects what gets DISPATCHED, and this path bypasses the dispatched value
 * entirely.
 */

import { beforeEach, describe, expect, it } from 'vitest';
import type { Env } from '../../../index';
import { generateWindowToken } from '../../../utils/jwt';
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import {
  createTestAgent,
  createTestEntity,
  createTestEvent,
  TestApiClient,
  TestWorkspace,
} from '../../setup/test-fixtures';

const JWT_ENV = { JWT_SECRET: 'test-jwt-secret-for-testing-only' } as Env;

async function createScheduledBehavior() {
  const sql = getTestDb();
  const workspace = await TestWorkspace.create({ name: 'Period Guard Org' });
  const entity = await createTestEntity({
    name: 'Period Guard Entity',
    organization_id: workspace.org.id,
    created_by: workspace.users.owner.id,
  });
  const agent = await createTestAgent({
    organizationId: workspace.org.id,
    ownerUserId: workspace.users.owner.id,
    agentId: 'period-guard-agent',
    name: 'Period Guard Agent',
  });

  const behavior = (await workspace.owner.behaviors.create({
    entity_id: entity.id,
    slug: 'period-guard-behavior',
    name: 'Period Guard Behavior',
    prompt: 'Summarize content for the bound entities.',
    triggers: [
      {
        kind: 'schedule',
        cron: '25 * * * *',
        execution: 'window',
        active_run: 'coalesce',
        skip_if_unchanged: false,
      },
    ],
    agent_id: agent.agentId,
  })) as { behavior_id: string };
  const watcherId = Number(behavior.behavior_id);

  const api = await TestApiClient.for({
    organizationId: workspace.org.id,
    userId: workspace.users.owner.id,
    memberRole: 'owner',
  });

  const event = await createTestEvent({
    entity_id: entity.id,
    organization_id: workspace.org.id,
    content: 'A post the radar would rank.',
    occurred_at: new Date(),
  });

  return { sql, workspace, api, watcherId, eventId: event.id };
}

/** A run in the state the worker sees it: claimed and running. */
async function seedRun(opts: {
  watcherId: number;
  orgId: string;
  windowStart: string;
  windowEnd: string;
  dispatchSource: 'scheduled' | 'manual';
}): Promise<number> {
  const sql = getTestDb();
  const [row] = (await sql`
    INSERT INTO runs (organization_id, watcher_id, run_type, status, approved_input, created_at)
    VALUES (
      ${opts.orgId}, ${opts.watcherId}, 'behavior', 'running',
      ${sql.json({
        watcher_id: opts.watcherId,
        window_start: opts.windowStart,
        window_end: opts.windowEnd,
        dispatch_source: opts.dispatchSource,
      } as never)},
      NOW()
    ) RETURNING id
  `) as Array<{ id: number }>;
  return Number(row.id);
}

function mintToken(watcherId: number, windowStart: string, windowEnd: string, eventId: number) {
  return generateWindowToken(
    {
      watcher_id: watcherId,
      window_start: windowStart,
      window_end: windowEnd,
      granularity: 'daily',
      content_count: 1,
      content_ids: [eventId],
    },
    JWT_ENV
  );
}

// The exact prod shape: dispatched the period that ends the previous day,
// completing the previous day's aligned start.
const DISPATCHED = '2026-07-30T23:59:59.999Z';
const DISPATCHED_END = '2026-07-31T23:59:59.999Z';
const AGENT_CHOSE = '2026-07-30T00:00:00.000Z';
const AGENT_CHOSE_END = '2026-07-30T23:59:59.999Z';

describe('scheduled Behavior window period guard', () => {
  beforeEach(async () => {
    await cleanupTestDatabase();
  });

  it('refuses a scheduled completion for a period other than the dispatched one', async () => {
    const { workspace, api, watcherId, eventId } = await createScheduledBehavior();
    const runId = await seedRun({
      watcherId,
      orgId: workspace.org.id,
      windowStart: DISPATCHED,
      windowEnd: DISPATCHED_END,
      dispatchSource: 'scheduled',
    });

    const token = await mintToken(watcherId, AGENT_CHOSE, AGENT_CHOSE_END, eventId);

    await expect(
      api.behaviors.completeWindow({
        behavior_id: String(watcherId),
        behavior_run_id: runId,
        window_token: token,
        extracted_data: { digest_title: 'Filed under the wrong day' },
      })
    ).rejects.toThrow(/dispatched for the period starting/);
  });

  // The message has to be actionable inside the same turn, or the agent has no
  // way back — it names both periods and the argument that caused the drift.
  it('names both periods and the cause so the agent can recover', async () => {
    const { workspace, api, watcherId, eventId } = await createScheduledBehavior();
    const runId = await seedRun({
      watcherId,
      orgId: workspace.org.id,
      windowStart: DISPATCHED,
      windowEnd: DISPATCHED_END,
      dispatchSource: 'scheduled',
    });
    const token = await mintToken(watcherId, AGENT_CHOSE, AGENT_CHOSE_END, eventId);

    const err = await api.behaviors
      .completeWindow({
        behavior_id: String(watcherId),
        behavior_run_id: runId,
        window_token: token,
        extracted_data: { digest_title: 'x' },
      })
      .then(
        () => null,
        (e: unknown) => (e instanceof Error ? e.message : String(e))
      );

    expect(err).toContain(DISPATCHED);
    expect(err).toContain(AGENT_CHOSE);
    expect(err).toContain('since');
  });

  it('writes NOTHING when it refuses — no root, no supersede', async () => {
    const { sql, workspace, api, watcherId, eventId } = await createScheduledBehavior();
    const runId = await seedRun({
      watcherId,
      orgId: workspace.org.id,
      windowStart: DISPATCHED,
      windowEnd: DISPATCHED_END,
      dispatchSource: 'scheduled',
    });
    const token = await mintToken(watcherId, AGENT_CHOSE, AGENT_CHOSE_END, eventId);

    await api.behaviors
      .completeWindow({
        behavior_id: String(watcherId),
        behavior_run_id: runId,
        window_token: token,
        extracted_data: { digest_title: 'x' },
      })
      .catch(() => undefined);

    const canvases = (await sql`
      SELECT 1 FROM events
      WHERE semantic_type = 'canvas_state'
        AND (metadata->>'watcher_id')::bigint = ${watcherId}
    `) as Array<unknown>;
    expect(canvases).toHaveLength(0);
  });

  it('accepts the dispatched period', async () => {
    const { sql, workspace, api, watcherId, eventId } = await createScheduledBehavior();
    const runId = await seedRun({
      watcherId,
      orgId: workspace.org.id,
      windowStart: DISPATCHED,
      windowEnd: DISPATCHED_END,
      dispatchSource: 'scheduled',
    });
    const token = await mintToken(watcherId, DISPATCHED, DISPATCHED_END, eventId);

    const completion = (await api.behaviors.completeWindow({
      behavior_id: String(watcherId),
      behavior_run_id: runId,
      window_token: token,
      extracted_data: { digest_title: 'Filed under the right day' },
    })) as { action: string; window_id: number };

    expect(completion.action).toBe('complete_window');

    const [row] = (await sql`
      SELECT metadata->>'window_start' AS window_start
      FROM events WHERE id = ${completion.window_id}
    `) as Array<{ window_start: string }>;
    expect(new Date(row.window_start).toISOString()).toBe(DISPATCHED);
  });

  // A manual or event run legitimately carries whatever period its caller chose
  // — backfilling an old range by hand must keep working.
  it('leaves a MANUAL run free to complete any period', async () => {
    const { workspace, api, watcherId, eventId } = await createScheduledBehavior();
    const runId = await seedRun({
      watcherId,
      orgId: workspace.org.id,
      windowStart: DISPATCHED,
      windowEnd: DISPATCHED_END,
      dispatchSource: 'manual',
    });
    const token = await mintToken(watcherId, AGENT_CHOSE, AGENT_CHOSE_END, eventId);

    const completion = (await api.behaviors.completeWindow({
      behavior_id: String(watcherId),
      behavior_run_id: runId,
      window_token: token,
      extracted_data: { digest_title: 'Deliberate backfill' },
    })) as { action: string };

    expect(completion.action).toBe('complete_window');
  });
});

